// AsGatewayPart0 returns the union data inside the GatewayPart as a GatewayPart0
func (t GatewayPart) AsGatewayPart0() (GatewayPart0, error) {
	var body GatewayPart0
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromGatewayPart0 overwrites any union data inside the GatewayPart as the provided GatewayPart0
func (t *GatewayPart) FromGatewayPart0(v GatewayPart0) error {
	b, err := json.Marshal(v)
	t.union = b
	return err
}

// MergeGatewayPart0 performs a merge with any union data inside the GatewayPart, using the provided GatewayPart0
func (t *GatewayPart) MergeGatewayPart0(v GatewayPart0) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

